# Entity Identity Graph - runnable demo (JAH-ATK187-000001)
RANK = 1
SIG = False
MENTIONS = [('m1', 'J. Smith', 'js@x.com'), ('m2', 'John Smith', 'js@x.com'), ('m3', 'J. Smith', 'other@y.com'), ('m4', 'Jane Doe', 'jd@x.com')]  # (mention_id, name, email_or_id)
parent = {m[0]: m[0] for m in MENTIONS}
def find(x):
    while parent[x] != x: parent[x] = parent[parent[x]]; x = parent[x]
    return x
def union(a, b): parent[find(a)] = find(b)
by_key = {}
for mid, name, key in MENTIONS:
    by_key.setdefault(("key", key), []).append(mid)
    by_key.setdefault(("name", name.lower()), []).append(mid)
for members in by_key.values():
    for m in members[1:]: union(members[0], m)
identities = {}
for mid, name, key in MENTIONS:
    identities.setdefault(find(mid), []).append((mid, name))
print("identities resolved:", len(identities))
for root, members in identities.items():
    canon = "ENT-" + root.upper()
    print(" ", canon, "<-", [m[1] for m in members])
if RANK >= 3:
    print("mentions:", len(MENTIONS))
if SIG:
    print("Signature lineage stamp: JAH-SIG-IDG-" + "JAH-ATK187-000001")
print("record:", "JAH-ATK187-000001", "OK")

